<?php
$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();
if(($_POST['action']??'practice')==='add_question'){
 $sid=(int)($_POST['subject_id']??0);$q=trim($_POST['question_text']??'');
 if(!$sid||$q===''){flash('Choose a subject and enter a question.','error');redirect('index.php?page=mcq');}
 $correct=$_POST['correct_option']??'A';
 $pdo->beginTransaction();
 try{$pdo->prepare('INSERT INTO questions(subject_id,question_text,correct_option,explanation,difficulty) VALUES(?,?,?,?,?)')->execute([$sid,$q,$correct,trim($_POST['explanation']??''),$_POST['difficulty']??'medium']);$qid=(int)$pdo->lastInsertId();$ins=$pdo->prepare('INSERT INTO options(question_id,option_label,option_text) VALUES(?,?,?)');foreach(['A','B','C','D'] as $letter){$ins->execute([$qid,$letter,trim($_POST['option_'.$letter]??'')]);}$pdo->commit();flash('Question added to your question bank.');}
 catch(Throwable $e){$pdo->rollBack();throw $e;}
 redirect('index.php?page=mcq');
}
$title=trim($_POST['title']??'Practice session');$subject=trim($_POST['subject']??'General');$count=max(1,min(100,(int)($_POST['quantity']??10)));$qs=$pdo->prepare("SELECT q.*,s.name subject_name FROM questions q LEFT JOIN subjects s ON s.id=q.subject_id WHERE (?='All' OR s.name=?) ORDER BY RAND() LIMIT ".$count);$qs->execute([$subject,$subject]);$questions=$qs->fetchAll();if(!$questions){flash('No questions found. Add questions to the question bank first.','error');redirect('index.php?page=mcq');}$_SESSION['mcq_session']=['title'=>$title,'ids'=>array_column($questions,'id')];redirect('index.php?page=mcq&run=1');}
if(isset($_GET['run'])&&isset($_SESSION['mcq_session'])){$ids=$_SESSION['mcq_session']['ids'];$in=implode(',',array_fill(0,count($ids),'?'));$st=$pdo->prepare("SELECT q.*,o.id option_id,o.option_label,o.option_text FROM questions q JOIN options o ON o.question_id=q.id WHERE q.id IN ($in) ORDER BY q.id,o.option_label");$st->execute($ids);$group=[];foreach($st->fetchAll() as $row){$group[$row['id']]['q']=$row; $group[$row['id']]['options'][]=$row;}?>
<div class="page-heading"><div><p class="eyebrow">ASSESSMENT CENTRE</p><h1><?=e($_SESSION['mcq_session']['title'])?></h1><p class="muted"><?=count($group)?> questions · Select one answer per question.</p></div></div>
<form class="card stack-form" method="post" action="api/submit_mcq.php"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="title" value="<?=e($_SESSION['mcq_session']['title'])?>">
<?php foreach($group as $id=>$item):?><fieldset class="question-box"><legend><?=e($item['q']['question_text'])?></legend><?php foreach($item['options'] as $o):?><label class="option-row"><input type="radio" name="answers[<?=$id?>]" value="<?=$o['option_label']?>" required><span><b><?=e($o['option_label'])?>.</b> <?=e($o['option_text'])?></span></label><?php endforeach;?></fieldset><?php endforeach;?><button class="btn primary">Submit answers</button></form>
<?php unset($_SESSION['mcq_session']); } else { $subjects=$pdo->query('SELECT id,name FROM subjects ORDER BY name')->fetchAll(); $questionCount=(int)$pdo->query('SELECT COUNT(*) FROM questions')->fetchColumn(); ?>
<div class="two-col"><section class="card"><h2>Start a practice session</h2><form method="post" class="stack-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Session title</label><input name="title" value="MCQ Practice" required><label>Subject</label><select name="subject"><option>All</option><?php foreach($subjects as $s):?><option><?=e($s['name'])?></option><?php endforeach;?></select><label>Number of questions</label><select name="quantity"><?php foreach([10,25,50,100] as $n):?><option value="<?=$n?>"><?=$n?></option><?php endforeach;?></select><button class="btn primary">Start practice</button></form></section><section class="card"><h2>Question bank</h2><p class="muted"><?=$questionCount?> questions available.</p><a class="btn secondary" href="index.php?page=revision">Review incorrect answers</a><hr><h2>Add a question</h2><?php if(!$subjects):?><p class="muted">Create a course and subject first in My Courses.</p><?php else:?><form method="post" class="stack-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_question"><label>Subject</label><select name="subject_id"><?php foreach($subjects as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?></option><?php endforeach;?></select><label>Question</label><textarea name="question_text" required rows="3"></textarea><?php foreach(['A','B','C','D'] as $letter):?><label>Option <?=$letter?></label><input name="option_<?=$letter?>" required><?php endforeach;?><label>Correct option</label><select name="correct_option"><?php foreach(['A','B','C','D'] as $letter):?><option><?=$letter?></option><?php endforeach;?></select><label>Difficulty</label><select name="difficulty"><option value="easy">Easy</option><option value="medium" selected>Medium</option><option value="hard">Hard</option></select><label>Explanation</label><textarea name="explanation"></textarea><button class="btn primary">Save question</button></form><?php endif;?></section></div><?php } ?>
